import itertools

names = ['Peter', 'Eric', 'Alice', 'Arnold']
smoothies = ['watermelon', 'desert', 'cherry', 'dragonfruit']
colors = ['green', 'white', 'red', 'yellow']

def solve():
    for name_perm in itertools.permutations(names):
        # Constraint 6: Peter's color is white -> we'll check later after colors assigned
        for smooth_perm in itertools.permutations(smoothies):
            # Constraint 1 & 3: dragonfruit lover is Eric and is in house 4 (index 3)
            if smooth_perm[3] != 'dragonfruit':
                continue
            idx_dragon = 3
            if name_perm[idx_dragon] != 'Eric':
                continue
            # Constraint 2: house 2 (index 1) likes cherry
            if smooth_perm[1] != 'cherry':
                continue
            # Constraint 4: Arnold likes watermelon
            try:
                idx_arnold = name_perm.index('Arnold')
            except ValueError:
                continue
            if smooth_perm[idx_arnold] != 'watermelon':
                continue
            for color_perm in itertools.permutations(colors):
                # Constraint 5: house 1 (index 0) color white
                if color_perm[0] != 'white':
                    continue
                # Constraint 6: Peter's color white
                idx_peter = name_perm.index('Peter')
                if color_perm[idx_peter] != 'white':
                    continue
                # Constraint 8: dragonfruit lover's color red
                if color_perm[idx_dragon] != 'red':
                    continue
                # Constraint 7: yellow lover is watermelon lover
                try:
                    idx_yellow = color_perm.index('yellow')
                except ValueError:
                    continue
                if smooth_perm[idx_yellow] != 'watermelon':
                    continue
                # All constraints satisfied; output solution
                for house in range(4):
                    print(f"House {house+1}: {name_perm[house]}, {smooth_perm[house]}, {color_perm[house]}")
                return

if __name__ == "__main__":
    solve()

