import itertools

houses = [1, 2]

names = ["Eric", "Arnold"]
musics = ["rock", "pop"]
styles = ["colonial", "victorian"]
lunches = ["grilled cheese", "pizza"]
sports = ["basketball", "soccer"]
children = ["Bella", "Fred"]

def satisfies(constraints):
    # constraints is a dict: house -> attrs dict
    # 1. colonial <-> pizza
    for h, a in constraints.items():
        if a["style"] == "colonial" and a["lunch"] != "pizza":
            return False
        if a["lunch"] == "pizza" and a["style"] != "colonial":
            return False
    # 2. Arnold lives in colonial house
    for a in constraints.values():
        if a["name"] == "Arnold" and a["style"] != "colonial":
            return False
    # 3. pop music same as colonial
    for a in constraints.values():
        if a["music"] == "pop" and a["style"] != "colonial":
            return False
        if a["style"] == "colonial" and a["music"] != "pop":
            return False
    # 4. pizza not in house 2
    if constraints[2]["lunch"] == "pizza":
        return False
    # 5. Eric loves soccer
    for a in constraints.values():
        if a["name"] == "Eric" and a["sport"] != "soccer":
            return False
    # 6. grilled cheese lover's child is Bella
    for a in constraints.values():
        if a["lunch"] == "grilled cheese" and a["child"] != "Bella":
            return False
        if a["child"] == "Bella" and a["lunch"] != "grilled cheese":
            return False
    return True

solution = None
# iterate over all permutations of each attribute set
for name_perm in itertools.permutations(names):
    for music_perm in itertools.permutations(musics):
        for style_perm in itertools.permutations(styles):
            for lunch_perm in itertools.permutations(lunches):
                for sport_perm in itertools.permutations(sports):
                    for child_perm in itertools.permutations(children):
                        assign = {}
                        for idx, house in enumerate(houses):
                            assign[house] = {
                                "name": name_perm[idx],
                                "music": music_perm[idx],
                                "style": style_perm[idx],
                                "lunch": lunch_perm[idx],
                                "sport": sport_perm[idx],
                                "child": child_perm[idx],
                            }
                        if satisfies(assign):
                            solution = assign
                            break
                    if solution:
                        break
                if solution:
                    break
            if solution:
                break
        if solution:
            break
    if solution:
        break

if solution:
    for house in sorted(solution):
        a = solution[house]
        print(f"House {house}: {a['name']}, {a['music']}, {a['style']}, {a['lunch']}, {a['sport']}, {a['child']}")

import itertools

names = ["Bob", "Alice", "Eric", "Arnold", "Peter"]
mothers = ["Aniya", "Janelle", "Penny", "Kailyn", "Holly"]
musics = ["pop", "jazz", "rock", "classical", "hip hop"]
lunches = ["grilled cheese", "stir fry", "stew", "spaghetti", "pizza"]

def solve():
    # 1. Permute names
    for name_perm in itertools.permutations(names):
        # positions are 0‑based indices
        pos = {n: i for i, n in enumerate(name_perm)}
        # Alice cannot be in house 1 (needs a mother left of her)
        if pos["Alice"] == 0:
            continue
        # Arnold cannot be in house 5 (his mother Kailyn must have a house to its right)
        if pos["Arnold"] == 4:
            continue

        # 2. Permute mothers with early constraints
        for mother_perm in itertools.permutations(mothers):
            # Arnold's mother is Kailyn (pop music ↔ Kailyn)
            if mother_perm[pos["Arnold"]] != "Kailyn":
                continue
            # Mother Kailyn directly left of Aniya
            try:
                kailyn_idx = mother_perm.index("Kailyn")
                if kailyn_idx == 4 or mother_perm[kailyn_idx + 1] != "Aniya":
                    continue
            except ValueError:
                continue
            # Mother Penny directly left of Alice
            alice_idx = pos["Alice"]
            if alice_idx == 0 or mother_perm[alice_idx - 1] != "Penny":
                continue

            # 3. Permute music with early constraints
            for music_perm in itertools.permutations(musics):
                # Arnold loves pop
                if music_perm[pos["Arnold"]] != "pop":
                    continue
                # Pop ↔ mother Kailyn (already ensured by Arnold's mother)
                if mother_perm[pos["Arnold"]] != "Kailyn":
                    continue
                # Alice loves jazz (spaghetti ↔ jazz)
                if music_perm[pos["Alice"]] != "jazz":
                    continue
                # Rock not in house 3 (index 2)
                if music_perm[2] == "rock":
                    continue

                # 4. Permute lunch with remaining constraints
                for lunch_perm in itertools.permutations(lunches):
                    # Peter's lunch is stir fry
                    if lunch_perm[pos["Peter"]] != "stir fry":
                        continue
                    # Alice's lunch is spaghetti
                    if lunch_perm[pos["Alice"]] != "spaghetti":
                        continue
                    # Spaghetti ↔ jazz already satisfied (Alice)

                    # Find grilled cheese position
                    try:
                        gc_idx = lunch_perm.index("grilled cheese")
                    except ValueError:
                        continue
                    # grilled cheese must have a house to its right
                    if gc_idx == 4:
                        continue
                    # grilled cheese directly left of stew
                    if lunch_perm[gc_idx + 1] != "stew":
                        continue
                    # mother of the stew house must be Janelle
                    if mother_perm[gc_idx + 1] != "Janelle":
                        continue

                    # All cross‑category constraints left:
                    # Eric left of classical music
                    try:
                        classical_idx = music_perm.index("classical")
                    except ValueError:
                        continue
                    if pos["Eric"] >= classical_idx:
                        continue
                    # Eric left of rock music
                    try:
                        rock_idx = music_perm.index("rock")
                    except ValueError:
                        continue
                    if pos["Eric"] >= rock_idx:
                        continue

                    # All clues satisfied – build output
                    result = []
                    for house in range(5):
                        result.append(
                            f"House {house+1}: {name_perm[house]}, {mother_perm[house]}, "
                            f"{music_perm[house]}, {lunch_perm[house]}"
                        )
                    return "\n".join(result)
    return "No solution found"

if __name__ == "__main__":
    print(solve())

import itertools
import sys

names = ["Carol", "Bob", "Peter", "Eric", "Alice", "Arnold"]
lunches = ["stir fry", "grilled cheese", "soup", "spaghetti", "stew", "pizza"]
styles = ["colonial", "victorian", "craftsman", "mediterranean", "ranch", "modern"]

# Helper to test constraints given the current partial mappings.
def constraints_ok(name_pos, lunch_pos, style_pos):
    # 1. ranch in house 5
    if "ranch" in style_pos and style_pos["ranch"] != 4:
        return False
    # 2. modern not in house 1
    if "modern" in style_pos and style_pos["modern"] == 0:
        return False
    # 3. stir fry directly left of Peter
    if "stir fry" in lunch_pos and "Peter" in name_pos:
        if lunch_pos["stir fry"] != name_pos["Peter"] - 1:
            return False
    # 4. one house between craftsman and Arnold
    if "craftsman" in style_pos and "Arnold" in name_pos:
        if abs(style_pos["craftsman"] - name_pos["Arnold"]) != 2:
            return False
    # 5. grilled cheese = Victorian
    if "grilled cheese" in lunch_pos and "victorian" in style_pos:
        if lunch_pos["grilled cheese"] != style_pos["victorian"]:
            return False
    # 6. stew = colonial
    if "stew" in lunch_pos and "colonial" in style_pos:
        if lunch_pos["stew"] != style_pos["colonial"]:
            return False
    # 7. soup directly left of pizza
    if "soup" in lunch_pos and "pizza" in lunch_pos:
        if lunch_pos["soup"] != lunch_pos["pizza"] - 1:
            return False
    # 8. Alice loves stew
    if "Alice" in name_pos and "stew" in lunch_pos:
        if name_pos["Alice"] != lunch_pos["stew"]:
            return False
    # 9. two houses between modern and Arnold
    if "modern" in style_pos and "Arnold" in name_pos:
        if abs(style_pos["modern"] - name_pos["Arnold"]) != 3:
            return False
    #10. stew not in house 6
    if "stew" in lunch_pos and lunch_pos["stew"] == 5:
        return False
    #11. Bob loves spaghetti
    if "Bob" in name_pos and "spaghetti" in lunch_pos:
        if name_pos["Bob"] != lunch_pos["spaghetti"]:
            return False
    #12. grilled cheese in house 2
    if "grilled cheese" in lunch_pos:
        if lunch_pos["grilled cheese"] != 1:
            return False
    #13. Carol not in house 4
    if "Carol" in name_pos and name_pos["Carol"] == 3:
        return False
    return True

solution = None

def backtrack(house, name_pos, lunch_pos, style_pos,
              remaining_names, remaining_lunches, remaining_styles):
    global solution
    if solution is not None:
        return
    if house == 6:                     # all houses assigned
        if constraints_ok(name_pos, lunch_pos, style_pos):
            solution = (name_pos, lunch_pos, style_pos)
        return

    # try every combination for this house
    for n in list(remaining_names):
        for l in list(remaining_lunches):
            for s in list(remaining_styles):
                # quick local checks that involve this house only
                # (clue 12: grilled cheese must be house 2)
                if l == "grilled cheese" and house != 1:
                    continue
                # (clue 1: ranch must be house 5)
                if s == "ranch" and house != 4:
                    continue
                # (clue 2: modern not house 1)
                if s == "modern" and house == 0:
                    continue
                # (clue 10: stew not house 6)
                if l == "stew" and house == 5:
                    continue
                # (clue 13: Carol not house 4)
                if n == "Carol" and house == 3:
                    continue

                # assign
                name_pos[n] = house
                lunch_pos[l] = house
                style_pos[s] = house

                # prune with any fully known constraints
                if constraints_ok(name_pos, lunch_pos, style_pos):
                    backtrack(house + 1,
                              name_pos, lunch_pos, style_pos,
                              remaining_names - {n},
                              remaining_lunches - {l},
                              remaining_styles - {s})

                # undo
                del name_pos[n]
                del lunch_pos[l]
                del style_pos[s]

                if solution is not None:
                    return

# start recursion
backtrack(0, {}, {}, {}, set(names), set(lunches), set(styles))

if solution is None:
    sys.exit("No solution found")

name_pos, lunch_pos, style_pos = solution

# Build inverse mappings: house -> attribute
house_name = [None] * 6
house_lunch = [None] * 6
house_style = [None] * 6
for n, p in name_pos.items():
    house_name[p] = n
for l, p in lunch_pos.items():
    house_lunch[p] = l
for s, p in style_pos.items():
    house_style[p] = s

# Print result
for i in range(6):
    print(f"House {i+1}: {house_name[i]}, {house_lunch[i]}, {house_style[i]}")

