                        continue
                    # Cat not in house 4 (index 3)
                    if pet_perm[3] == 'cat':
                        continue
                    # Cat lives in Mediterranean style house
                    cat_house = idx_of(pet_perm, 'cat')
                    if style_perm[cat_house] != 'mediterranean':
                        continue
                    # Bird pet uses Google Pixel 6
                    bird_house = idx_of(pet_perm, 'bird')
                    if phone_perm[bird_house] != 'google pixel 6':
                        continue
                    # Bird is directly left of Xiaomi Mi 11 user
                    if idx_of(phone_perm, 'xiaomi mi 11') != bird_house + 1:
                        continue
                    # Ranch style left of Classical music
                    if idx_of(style_perm, 'ranch') >= idx_of(music_perm, 'classical'):
                        continue

                    # All constraints satisfied; record solution
                    solutions.append((name_perm, music_perm, style_perm, phone_perm, pet_perm))
                    break  # assuming unique solution, exit inner loop

                if solutions:
                    break
            if solutions:
                break
        if solutions:
            break
    if solutions:
        break

# Print the unique solution
if solutions:
