import itertools

# Data
names = ["Peter", "Eric", "Arnold", "Alice", "Bob"]
phones = [
    "google pixel 6",
    "samsung galaxy s21",
    "huawei p50",
    "oneplus 9",
    "iphone 13",
]

# Fixed positions
fixed_name = {5: "Alice", 1: "Bob"}          # house -> name
fixed_phone = {1: "huawei p50"}             # house -> phone

# Remaining names for houses 2‑4
remaining_names = [n for n in names if n not in fixed_name.values()]
# Remaining phones for houses 2‑5
remaining_phones = [p for p in phones if p not in fixed_phone.values()]

solution = None

# Iterate over permutations of the unfixed names
for perm_names in itertools.permutations(remaining_names):
    # Build house -> name mapping (1‑based indexing)
    house_name = {}
    house_name.update(fixed_name)
    for idx, name in enumerate(perm_names, start=2):
        house_name[idx] = name

    # Helper: find house of a given name
    def house_of_name(target):
        for h, n in house_name.items():
            if n == target:
                return h
        return None

    # Iterate over permutations of the unfixed phones
    for perm_phones in itertools.permutations(remaining_phones):
        house_phone = {}
        house_phone.update(fixed_phone)
        for idx, phone in enumerate(perm_phones, start=2):
            house_phone[idx] = phone

        # Helper: find house of a given phone
        def house_of_phone(target):
            for h, p in house_phone.items():
                if p == target:
                    return h
            return None

        # ----- Check all constraints -----
        # 1. Eric uses Samsung Galaxy S21
        if house_phone[house_of_name("Eric")] != "samsung galaxy s21":
            continue

        # 3. Samsung left of Google Pixel
        if house_of_phone("samsung galaxy s21") >= house_of_phone("google pixel 6"):
            continue

        # 4. Arnold directly left of OnePlus 9
        if house_of_name("Arnold") != house_of_phone("oneplus 9") - 1:
            continue

        # 5. Bob uses Huawei P50 (already enforced by fixed placements)
        if house_phone[house_of_name("Bob")] != "huawei p50":
            continue

        # 6. iPhone 13 directly left of OnePlus 9
        if house_of_phone("iphone 13") != house_of_phone("oneplus 9") - 1:
            continue

        # 7. Huawei P50 in first house (already enforced)
        if house_phone[1] != "huawei p50":
            continue

        # 8. Google Pixel left of OnePlus 9
        if house_of_phone("google pixel 6") >= house_of_phone("oneplus 9"):
            continue

        # All constraints satisfied
        solution = (house_name, house_phone)
        break
    if solution:
        break

# Output
if solution:
    house_name, house_phone = solution
    for house in range(1, 6):
        print(f"House {house}: {house_name[house]}, {house_phone[house]}")
else:
    print("No solution found.")

import itertools

# Domain values
names = ["Eric", "Arnold"]
phones = ["iphone 13", "samsung galaxy s21"]
drinks = ["water", "tea"]
sports = ["basketball", "soccer"]

# Helper to check all constraints on a candidate assignment
def valid(assignment):
    # assignment is a dict: house -> dict of attributes
    # Constraint 1: Arnold is in house 2
    if assignment[2]["name"] != "Arnold":
        return False
    # Constraint 2: Samsung user not in house 1
    if assignment[1]["phone"] == "samsung galaxy s21":
        return False
    # Constraint 3: Eric loves soccer
    for h in (1, 2):
        if assignment[h]["name"] == "Eric" and assignment[h]["sport"] != "soccer":
            return False
    # Constraint 4: Samsung user drinks tea
    for h in (1, 2):
        if assignment[h]["phone"] == "samsung galaxy s21" and assignment[h]["drink"] != "tea":
            return False
    return True

# Generate all bijective assignments for each attribute category
for name_perm in itertools.permutations(names):
    for phone_perm in itertools.permutations(phones):
        for drink_perm in itertools.permutations(drinks):
            for sport_perm in itertools.permutations(sports):
                # Build the two‑house structure
                assignment = {
                    1: {
                        "name": name_perm[0],
                        "phone": phone_perm[0],
                        "drink": drink_perm[0],
                        "sport": sport_perm[0],
                    },
                    2: {
                        "name": name_perm[1],
                        "phone": phone_perm[1],
                        "drink": drink_perm[1],
                        "sport": sport_perm[1],
                    },
                }
                if valid(assignment):
                    # Print in required format
                    for house in (1, 2):
                        attrs = assignment[house]
                        print(f"House {house}: {attrs['name']}, {attrs['phone']}, {attrs['drink']}, {attrs['sport']}")
                    raise SystemExit

