import itertools

# Attribute domains
NAMES = ["Bob", "Arnold", "Alice", "Peter", "Eric"]
HOBBIES = ["cooking", "gardening", "painting", "photography", "knitting"]
SPORTS = ["swimming", "tennis", "soccer", "baseball", "basketball"]
STYLES = ["ranch", "craftsman", "victorian", "modern", "colonial"]
CHILDREN = ["Timothy", "Samantha", "Bella", "Meredith", "Fred"]
HEIGHTS = ["average", "very tall", "very short", "short", "tall"]

HOUSE_COUNT = 5
IDX = range(HOUSE_COUNT)

def check_partial(names, hobbies, sports, styles, children, heights):
    # helper to find index of a value in a list (or None)
    def idx_of(lst, val):
        try:
            return lst.index(val)
        except ValueError:
            return None

    # 1. average height ↔ child Meredith
    for i in IDX:
        if heights[i] == "average" and children[i] not in (None, "Meredith"):
            return False
        if children[i] == "Meredith" and heights[i] not in (None, "average"):
            return False

    # 2. house 2 (index 1) height tall
    if heights[1] not in (None, "tall"):
        return False

    # 3. Peter directly left of Victorian house
    p_idx = idx_of(names, "Peter")
    v_idx = idx_of(styles, "victorian")
    if p_idx is not None and v_idx is not None and p_idx + 1 != v_idx:
        return False
    if p_idx is not None and v_idx is None and p_idx == HOUSE_COUNT - 1:
        return False
    if v_idx is not None and p_idx is None and v_idx == 0:
        return False

    # 4. Alice height tall
    a_idx = idx_of(names, "Alice")
    if a_idx is not None and heights[a_idx] not in (None, "tall"):
        return False
    if heights[a_idx] == "tall" and a_idx is not None and names[a_idx] not in (None, "Alice"):
        return False

    # 5. baseball → very tall
    for i in IDX:
        if sports[i] == "baseball" and heights[i] not in (None, "very tall"):
            return False

    # 6. child Meredith adjacent to child Timothy
    m_idx = idx_of(children, "Meredith")
    t_idx = idx_of(children, "Timothy")
    if m_idx is not None and t_idx is not None and abs(m_idx - t_idx) != 1:
        return False

    # 7. Bob hobby painting
    b_idx = idx_of(names, "Bob")
    if b_idx is not None and hobbies[b_idx] not in (None, "painting"):
        return False
    if hobbies[b_idx] == "painting" and b_idx is not None and names[b_idx] not in (None, "Bob"):
        return False

    # 8. house 2 hobby gardening (already set in main loop)

    # 9. very short right of Eric
    vs_idx = idx_of(heights, "very short")
    e_idx = idx_of(names, "Eric")
    if vs_idx is not None and e_idx is not None and vs_idx <= e_idx:
        return False

    #10. tennis → child Samantha
    for i in IDX:
        if sports[i] == "tennis" and children[i] not in (None, "Samantha"):
            return False

    #11. soccer not in house 1 (index 0)
    if sports[0] == "soccer":
        return False

    #12. child Samantha → style modern
    s_idx = idx_of(children, "Samantha")
    if s_idx is not None and styles[s_idx] not in (None, "modern"):
        return False

    #13. craftsman ↔ average height
    for i in IDX:
        if styles[i] == "craftsman" and heights[i] not in (None, "average"):
            return False
        if heights[i] == "average" and styles[i] not in (None, "craftsman"):
            return False

    #14. child Fred → style Victorian (handled by fixed placements)

    #15. short → basketball
    for i in IDX:
        if heights[i] == "short" and sports[i] not in (None, "basketball"):
            return False

    #16. Peter very tall (handled)

    #17. ranch left of cooking
    r_idx = idx_of(styles, "ranch")
    c_idx = idx_of(hobbies, "cooking")
    if r_idx is not None and c_idx is not None and r_idx >= c_idx:
        return False

    #18. knitting adjacent to gardening
    k_idx = idx_of(hobbies, "knitting")
    g_idx = idx_of(hobbies, "gardening")
    if k_idx is not None and g_idx is not None and abs(k_idx - g_idx) != 1:
        return False

    #19. modern → cooking
    for i in IDX:
        if styles[i] == "modern" and hobbies[i] not in (None, "cooking"):
            return False

    #20. Victorian house is house 5 (index 4)
    if styles[4] not in (None, "victorian"):
        return False
    if styles[4] == "victorian" and any(styles[i] == "victorian" for i in range(4)):
        return False

    return True

def solve():
    # Fixed placements from clues
    names = [None] * HOUSE_COUNT
    hobbies = [None] * HOUSE_COUNT
    sports = [None] * HOUSE_COUNT
    styles = [None] * HOUSE_COUNT
    children = [None] * HOUSE_COUNT
    heights = [None] * HOUSE_COUNT

    names[1] = "Alice"
    heights[1] = "tall"
    hobbies[1] = "gardening"

    names[3] = "Peter"
    heights[3] = "very tall"
    sports[3] = "baseball"

    styles[4] = "victorian"
    children[4] = "Fred"

    # Remaining values for each category
    remaining_names = [n for n in NAMES if n not in ("Alice", "Peter")]
    remaining_heights = [h for h in HEIGHTS if h not in ("tall", "very tall")]
    remaining_styles = [s for s in STYLES if s != "victorian"]
    remaining_children = [c for c in CHILDREN if c != "Fred"]
    remaining_hobbies = [h for h in HOBBIES if h != "gardening"]
    remaining_sports = [s for s in SPORTS if s != "baseball"]

    name_positions = [0, 2, 4]          # houses still empty for names
    height_positions = [0, 2, 4]
    style_positions = [0, 1, 2, 3]
    child_positions = [0, 1, 2, 3]
    hobby_positions = [0, 2, 3, 4]
    sport_positions = [0, 1, 2, 4]

    for perm_names in itertools.permutations(remaining_names):
        for pos, val in zip(name_positions, perm_names):
            names[pos] = val
        if not check_partial(names, hobbies, sports, styles, children, heights):
            continue

        for perm_heights in itertools.permutations(remaining_heights):
            for pos, val in zip(height_positions, perm_heights):
                heights[pos] = val
            if not check_partial(names, hobbies, sports, styles, children, heights):
                continue

            for perm_styles in itertools.permutations(remaining_styles):
                for pos, val in zip(style_positions, perm_styles):
                    styles[pos] = val
                if not check_partial(names, hobbies, sports, styles, children, heights):
                    continue

                for perm_children in itertools.permutations(remaining_children):
                    for pos, val in zip(child_positions, perm_children):
                        children[pos] = val
                    if not check_partial(names, hobbies, sports, styles, children, heights):
                        continue

                    for perm_hobbies in itertools.permutations(remaining_hobbies):
                        for pos, val in zip(hobby_positions, perm_hobbies):
                            hobbies[pos] = val
                        if not check_partial(names, hobbies, sports, styles, children, heights):
                            continue

                        for perm_sports in itertools.permutations(remaining_sports):
                            for pos, val in zip(sport_positions, perm_sports):
                                sports[pos] = val
                            if not check_partial(names, hobbies, sports, styles, children, heights):
                                continue

                            # All constraints satisfied – print solution
                            for i in IDX:
                                print(f"House {i+1}: {names[i]}, {hobbies[i]}, {sports[i]}, {styles[i]}, {children[i]}, {heights[i]}")
                            return

solve()

