# Helper to check all constraints given current partial mappings
def constraints_ok(assignments, maps):
    # maps contain attribute->house index (or None if not assigned)
    n2h = maps["name"]
    h2h = maps["height"]
    d2h = maps["drink"]
    c2h = maps["child"]
    m2h = maps["mother"]

    # 1. Tall is Arnold
    if n2h.get("Arnold") is not None and h2h.get("tall") is not None:
        if n2h["Arnold"] != h2h["tall"]:
            return False
    # 2. Child Samantha -> tea
