    if m2h.get("Holly") is not None and d2h.get("coffee") is not None:
        if m2h["Holly"] != d2h["coffee"]:
            return False
    # 4. Samantha adjacent to Holly
    if c2h.get("Samantha") is not None and m2h.get("Holly") is not None:
        if abs(c2h["Samantha"] - m2h["Holly"]) != 1:
            return False
    # 5. Meredith adjacent to very short
    if c2h.get("Meredith") is not None and h2h.get("very short") is not None:
