            return False
    # 8. Alice -> child Fred
    if n2h.get("Alice") is not None and c2h.get("Fred") is not None:
        if n2h["Alice"] != c2h["Fred"]:
            return False
    # 9. Peter adjacent to very short
    if n2h.get("Peter") is not None and h2h.get("very short") is not None:
        if abs(n2h["Peter"] - h2h["very short"]) != 1:
            return False
