    for perm_name in permutations(names):
        name_to_house = {name: i for i, name in enumerate(perm_name)}
        # early check: Arnold must be tall later after heights assigned
        # continue to heights
        for perm_height in permutations(heights):
            height_to_house = {h: i for i, h in enumerate(perm_height)}
            # check constraints that involve only name & height
            maps = {"name": name_to_house, "height": height_to_house,
