#!/usr/bin/env python3
import sys
from itertools import product

# ----- data ---------------------------------------------------------

names = ["Eric", "Peter", "Alice", "Arnold"]
hairs = ["brown", "black", "blonde", "red"]
sports = ["tennis", "basketball", "soccer", "swimming"]
smoothies = ["watermelon", "cherry", "dragonfruit", "desert"]
months = ["april", "sept", "feb", "jan"]
phones = ["oneplus 9", "samsung galaxy s21", "iphone 13", "google pixel 6"]

ATTRS = ["name", "hair", "sport", "smoothie", "month", "phone"]

# ----- helper --------------------------------------------------------

def house_of(value, assignments, attr):
    """return house number where given value is already placed, else None"""
    for h, a in assignments.items():
        if a[attr] == value:
            return h
    return None

def adjacent(a, b):
    return abs(a - b) == 1

def left_of(a, b):
    return a < b

def right_of(a, b):
    return a > b

# ----- constraint checking -------------------------------------------

def check_partial(assignments):
    """return False if any clue is already violated by the partial map"""
    # convenience look‑ups
    def pos(attr, val):
        return house_of(val, assignments, attr)

    # 1. Jan left of basketball
    p_jan = pos("month", "jan")
    p_basket = pos("sport", "basketball")
    if p_jan and p_basket and not left_of(p_jan, p_basket):
        return False

    # 2. Feb directly left of red hair
    p_feb = pos("month", "feb")
    p_red = pos("hair", "red")
    if p_feb and p_red and not (p_feb + 1 == p_red):
        return False

    # 3. Eric uses OnePlus 9
    p_eric = pos("name", "Eric")
    p_oneplus = pos("phone", "oneplus 9")
    if p_eric and p_oneplus and p_eric != p_oneplus:
        return False

    # 4. April is Arnold
    p_april = pos("month", "april")
    p_arnold = pos("name", "Arnold")
    if p_april and p_arnold and p_april != p_arnold:
        return False

    # 5. Samsung and Cherry are neighbours
    p_sam = pos("phone", "samsung galaxy s21")
    p_cherry = pos("smoothie", "cherry")
    if p_sam and p_cherry and not adjacent(p_sam, p_cherry):
        return False

    # 6. Blonde hair and Peter are neighbours
    p_blonde = pos("hair", "blonde")
    p_peter = pos("name", "Peter")
    if p_blonde and p_peter and not adjacent(p_blonde, p_peter):
        return False

    # 7. Black hair somewhere right of brown hair
    p_black = pos("hair", "black")
    p_brown = pos("hair", "brown")
    if p_black and p_brown and not right_of(p_black, p_brown):
        return False

    # 8. Black hair = Feb month
    if p_black and p_feb and p_black != p_feb:
        return False

    # 9. Dragonfruit smoothie is house 2
    p_dragon = pos("smoothie", "dragonfruit")
    if p_dragon and p_dragon != 2:
        return False

    #10. Soccer right of OnePlus user
    p_soccer = pos("sport", "soccer")
    if p_oneplus and p_soccer and not right_of(p_soccer, p_oneplus):
        return False

    #11. Two houses between tennis and basketball (distance 3)
    p_tennis = pos("sport", "tennis")
    if p_tennis and p_basket and abs(p_tennis - p_basket) != 3:
        return False

    #12. Black hair = Samsung phone
    if p_black and p_sam and p_black != p_sam:
        return False

    #13. Alice likes Cherry smoothie
    p_alice = pos("name", "Alice")
    p_cherry = pos("smoothie", "cherry")
    if p_alice and p_cherry and p_alice != p_cherry:
        return False

    #14. Desert smoothie = Google Pixel 6
    p_desert = pos("smoothie", "desert")
    p_google = pos("phone", "google pixel 6")
    if p_desert and p_google and p_desert != p_google:
        return False

    return True

def check_complete(assignments):
    """all clues must hold when every house is assigned"""
    return check_partial(assignments)

# ----- backtracking search -------------------------------------------

def solve():
    # start with full pools
    pools = {
        "name": set(names),
        "hair": set(hairs),
        "sport": set(sports),
        "smoothie": set(smoothies),
        "month": set(months),
        "phone": set(phones),
    }
    assignments = {}          # house -> attr dict

    def backtrack(house):
        if house > 4:                     # all houses filled
            if check_complete(assignments):
                return assignments
            return None

        # iterate over all possible combinations of remaining values
        for name in list(pools["name"]):
            # early pruning for Eric‑OnePlus relation
            if name == "Eric" and "oneplus 9" not in pools["phone"]:
                continue
            if name != "Eric" and "oneplus 9" in pools["phone"] and len(pools["phone"]) == 1:
                continue

            for hair in list(pools["hair"]):
                # black hair must be feb month & Samsung phone – can't check yet
                for sport in list(pools["sport"]):
                    for smoothie in list(pools["smoothie"]):
                        # dragonfruit must be house 2
                        if smoothie == "dragonfruit" and house != 2:
                            continue
                        # Alice must have cherry – can prune if name is Alice
                        if name == "Alice" and smoothie != "cherry":
                            continue
                        if smoothie == "cherry" and name != "Alice":
                            continue
                        for month in list(pools["month"]):
                            # Arnold is april
                            if name == "Arnold" and month != "april":
                                continue
                            if month == "april" and name != "Arnold":
                                continue
                            # black hair = feb month
                            if hair == "black" and month != "feb":
                                continue
                            if month == "feb" and hair != "black":
                                continue
                            for phone in list(pools["phone"]):
                                # Eric = OnePlus
                                if name == "Eric" and phone != "oneplus 9":
                                    continue
                                if phone == "oneplus 9" and name != "Eric":
                                    continue
                                # black hair = Samsung
                                if hair == "black" and phone != "samsung galaxy s21":
                                    continue
                                if phone == "samsung galaxy s21" and hair != "black":
                                    continue
                                # desert smoothie = Google Pixel
                                if smoothie == "desert" and phone != "google pixel 6":
                                    continue
                                if phone == "google pixel 6" and smoothie != "desert":
                                    continue

                                # make tentative assignment
                                assignments[house] = {
                                    "name": name,
                                    "hair": hair,
                                    "sport": sport,
                                    "smoothie": smoothie,
                                    "month": month,
                                    "phone": phone,
                                }
                                # remove used values from pools
                                removed = {}
                                for attr, val in assignments[house].items():
                                    pools[attr].remove(val)
                                    removed[attr] = val

                                if check_partial(assignments):
                                    result = backtrack(house + 1)
                                    if result:
                                        return result

                                # backtrack: restore pools
                                for attr, val in removed.items():
                                    pools[attr].add(val)
                                del assignments[house]

        return None

    return backtrack(1)

def main():
    solution = solve()
    if not solution:
        print("No solution found", file=sys.stderr)
        sys.exit(1)

    # output in required order
    for h in range(1, 5):
        a = solution[h]
        print(f"House {h}: {a['name']}, {a['hair']}, {a['sport']}, {a['smoothie']}, {a['month']}, {a['phone']}")

if __name__ == "__main__":
    main()

