# ----- backtracking search -------------------------------------------

def solve(state, remaining):
    """depth‑first search.
    state  – current house dicts
    remaining – dict of remaining values for each category"""
    # if every house is fully assigned, we have a solution
    if all(len(state[h]) == 5 for h in range(1, 6)):
        return state

    # choose the house with the fewest missing attributes
    # (simple heuristic)
    def missing_cnt(h):
        return 5 - len(state[h])
    house = min((h for h in range(1, 6) if len(state[h]) < 5), key=missing_cnt)

    # determine which categories are still unset for this house
    unset = [cat for cat in ["name", "phone", "smoothie", "mother", "occupation"]
             if cat not in state[house]]

    # iterate over Cartesian product of possible values for the unset categories
    # but prune using remaining sets
    for values in itertools.product(*[remaining[cat] for cat in unset]):
        # build a tentative assignment
        new_state = {h: dict(state[h]) for h in state}
        new_remaining = {cat: set(remaining[cat]) for cat in remaining}
        ok = True
        for cat, val in zip(unset, values):
            # uniqueness check
            if val not in new_remaining[cat]:
                ok = False
                break
            new_state[house][cat] = val
            new_remaining[cat].remove(val)
        if not ok:
            continue
        if not check_partial(new_state):
            continue
        result = solve(new_state, new_remaining)
        if result:
            return result
    return None

# initialise remaining sets after the forced assignments
