import itertools

names = ["Arnold", "Peter", "Eric"]
lunches = ["spaghetti", "grilled cheese", "pizza"]
colors = ["yellow", "white", "red"]

def solve():
    solutions = []
    # permutations for each attribute across the three houses (order = house 1,2,3)
    for name_perm in itertools.permutations(names):
        for lunch_perm in itertools.permutations(lunches):
            for color_perm in itertools.permutations(colors):
                # Helper to find index of a particular attribute
                def idx_of(attr_list, value):
                    return attr_list.index(value)

                # Constraint 5: spaghetti eater is Eric
                try:
                    spaghetti_idx = idx_of(lunch_perm, "spaghetti")
                except ValueError:
                    continue
                if name_perm[spaghetti_idx] != "Eric":
                    continue

                # Constraint 2: spaghetti eater loves yellow
                if color_perm[spaghetti_idx] != "yellow":
                    continue

                # Constraint 4: Peter is directly left of spaghetti eater
                try:
                    peter_idx = idx_of(name_perm, "Peter")
                except ValueError:
                    continue
                if peter_idx + 1 != spaghetti_idx:
                    continue

                # Constraint 1: red and yellow are neighbours
                try:
                    red_idx = idx_of(color_perm, "red")
                    yellow_idx = idx_of(color_perm, "yellow")
                except ValueError:
                    continue
                if abs(red_idx - yellow_idx) != 1:
                    continue

                # Constraint 3: pizza and red are neighbours
                try:
                    pizza_idx = idx_of(lunch_perm, "pizza")
                except ValueError:
                    continue
                if abs(pizza_idx - red_idx) != 1:
                    continue

                # All constraints satisfied – store the solution
                solutions.append((name_perm, lunch_perm, color_perm))

    # There should be exactly one solution
    if not solutions:
        raise RuntimeError("No solution found")
    name_sol, lunch_sol, color_sol = solutions[0]

    # Print in the required format
    for house in range(3):
        print(f"House {house + 1}: {name_sol[house]}, {lunch_sol[house]}, {color_sol[house]}")

