import sys

names = ["Alice", "Carol", "Eric", "Peter", "Arnold", "Bob"]
smoothies = ["watermelon", "dragonfruit", "lime", "desert", "blueberry", "cherry"]
cigars = ["pall mall", "yellow monster", "dunhill", "blends", "blue master", "prince"]
houses = range(1, 7)

def solve():
    # Pre‑assign the known fixed clue: house 3 has lime smoothie
    fixed_smoothie = {3: "lime"}

    # Backtracking over houses
    def backtrack(h, name_at, smoothie_at, cigar_at,
                  used_names, used_smoothies, used_cigars):
        if h > 6:
            # All houses assigned, verify all constraints one last time
            if check_all(name_at, smoothie_at, cigar_at):
                return name_at, smoothie_at, cigar_at
            return None

        # Determine possible values for this house
        possible_names = [n for n in names if n not in used_names]
        possible_smoothies = [s for s in smoothies if s not in used_smoothies]
        possible_cigars = [c for c in cigars if c not in used_cigars]

        # Enforce clue 1: house 3 must be lime
        if h == 3:
            if "lime" not in possible_smoothies:
                return None
            possible_smoothies = ["lime"]

        for name in possible_names:
            # Early prune for clues involving name only
            if name == "Bob":
                # clue 9 will be checked later when Carol is placed
                pass
            if name == "Peter":
                # clue 12: Peter must smoke blue master
                if "blue master" not in possible_cigars:
                    continue
            for smoothie in possible_smoothies:
                # clue 2 & 3 equivalences may prune
                # If smoothie is watermelon, cigar must be pall mall (and vice‑versa)
                if smoothie == "watermelon" and "pall mall" not in possible_cigars:
                    continue
                # If smoothie is desert, name must be Arnold (and vice‑versa)
                if smoothie == "desert" and name != "Arnold":
                    continue
                if name == "Arnold" and smoothie != "desert":
                    continue
                # If smoothie is cherry, cigar must be dunhill (and vice‑versa)
                if smoothie == "cherry" and "dunhill" not in possible_cigars:
                    continue
                # If smoothie is dragonfruit, cigar must be prince (and vice‑versa)
                if smoothie == "dragonfruit" and "prince" not in possible_cigars:
                    continue

                for cigar in possible_cigars:
                    # Enforce equivalence clues immediately
                    if cigar == "pall mall" and smoothie != "watermelon":
                        continue
                    if smoothie == "watermelon" and cigar != "pall mall":
                        continue
                    if cigar == "blue master" and name != "Peter":
                        continue
                    if name == "Peter" and cigar != "blue master":
                        continue
                    if cigar == "dunhill" and smoothie != "cherry":
                        continue
                    if smoothie == "cherry" and cigar != "dunhill":
                        continue
                    if cigar == "prince" and smoothie != "dragonfruit":
                        continue
                    if smoothie == "dragonfruit" and cigar != "prince":
                        continue

                    # Tentatively assign
                    name_at[h] = name
                    smoothie_at[h] = smoothie
                    cigar_at[h] = cigar
                    used_names.add(name)
                    used_smoothies.add(smoothie)
                    used_cigars.add(cigar)

                    # Check constraints that are decidable with current partial info
                    if not partial_ok(name_at, smoothie_at, cigar_at):
                        # undo and continue
                        used_names.remove(name)
                        used_smoothies.remove(smoothie)
                        used_cigars.remove(cigar)
                        del name_at[h]
                        del smoothie_at[h]
                        del cigar_at[h]
                        continue

                    result = backtrack(h + 1, name_at, smoothie_at, cigar_at,
                                      used_names, used_smoothies, used_cigars)
                    if result:
                        return result

                    # backtrack
                    used_names.remove(name)
                    used_smoothies.remove(smoothie)
                    used_cigars.remove(cigar)
                    del name_at[h]
                    del smoothie_at[h]
                    del cigar_at[h]

        return None

    # Helper to locate house of a given attribute in current partial assignment
    def house_of_name(name):
        for h, n in name_at.items():
            if n == name:
                return h
        return None

    def house_of_smoothie(smooth):
        for h, s in smoothie_at.items():
            if s == smooth:
                return h
        return None

    def house_of_cigar(cig):
        for h, c in cigar_at.items():
            if c == cig:
                return h
        return None

    # Checks that are safe to evaluate with partial information
    def partial_ok(name_at, smoothie_at, cigar_at):
        # Helper closures
        def get_house(mapping, value):
            for h, v in mapping.items():
                if v == value:
                    return h
            return None

        # Clue 4: watermelon left of Eric
        w_house = get_house(smoothie_at, "watermelon")
        e_house = get_house(name_at, "Eric")
        if w_house and e_house and not (w_house < e_house):
            return False

        # Clue 5: one house between Peter and Carol
        p_house = get_house(name_at, "Peter")
        c_house = get_house(name_at, "Carol")
        if p_house and c_house and not (abs(p_house - c_house) == 2):
            return False

        # Clue 6: blueberry left of lime
        b_house = get_house(smoothie_at, "blueberry")
        l_house = get_house(smoothie_at, "lime")
        if b_house and l_house and not (b_house < l_house):
            return False

        # Clue 7: watermelon left of blends smoker
        blends_house = get_house(cigar_at, "blends")
        if w_house and blends_house and not (w_house < blends_house):
            return False

        # Clue 8: dragonfruit adjacent to Carol
        d_house = get_house(smoothie_at, "dragonfruit")
        if d_house and c_house and not (abs(d_house - c_house) == 1):
            return False

        # Clue 9: Bob directly left of Carol
        bob_house = get_house(name_at, "Bob")
        if bob_house and c_house and not (bob_house + 1 == c_house):
            return False

        # Clue 13: watermelon adjacent to desert
        desert_house = get_house(smoothie_at, "desert")
        if w_house and desert_house and not (abs(w_house - desert_house) == 1):
            return False

        return True

    # Final full verification (all constraints)
    def check_all(name_at, smoothie_at, cigar_at):
        # Helper
        def house_of(mapping, val):
            for h, v in mapping.items():
                if v == val:
                    return h
            return None

        # 1
        if smoothie_at[3] != "lime":
            return False
        # 2
        if not (cigar_of("pall mall") == house_of(smoothie_at, "watermelon")):
            return False
        # 3
        if not (name_of(house_of(smoothie_at, "desert")) == "Arnold"):
            return False
        # 4
        if not (house_of(smoothie_at, "watermelon") < house_of(name_at, "Eric")):
            return False
        # 5
        if not (abs(house_of(name_at, "Peter") - house_of(name_at, "Carol")) == 2):
            return False
        # 6
        if not (house_of(smoothie_at, "blueberry") < house_of(smoothie_at, "lime")):
            return False
        # 7
        if not (house_of(smoothie_at, "watermelon") < house_of(cigar_at, "blends")):
            return False
        # 8
        if not (abs(house_of(smoothie_at, "dragonfruit") - house_of(name_at, "Carol")) == 1):
            return False
        # 9
        if not (house_of(name_at, "Bob") + 1 == house_of(name_at, "Carol")):
            return False
        #10
        if not (cigar_of("dunhill") == house_of(smoothie_at, "cherry")):
            return False
        #11
        if not (cigar_of("prince") == house_of(smoothie_at, "dragonfruit")):
            return False
        #12
        if not (cigar_of("blue master") == house_of(name_at, "Peter")):
            return False
        #13
        if not (abs(house_of(smoothie_at, "watermelon") - house_of(smoothie_at, "desert")) == 1):
            return False
        return True

    # Helper to get house of a cigar
    def cigar_of(cig):
        for h, c in cigar_at.items():
            if c == cig:
                return h
        return None

    # Helper to get name at house
    def name_of(h):
        return name_at.get(h)

    # Start recursion
    name_at = {}
    smoothie_at = {}
    cigar_at = {}
    result = backtrack(1, name_at, smoothie_at, cigar_at,
