import itertools
import sys

names = ["Alice", "Peter", "Arnold", "Bob", "Carol", "Eric"]
hairs = ["red", "brown", "blonde", "black", "gray", "auburn"]
occs  = ["engineer", "lawyer", "nurse", "doctor", "artist", "teacher"]

# Helper to test adjacency
def adjacent(i, j):
    return abs(i - j) == 1

def solve():
    # Pre‑compute fixed name‑related constraints
    name_fixed_hair = {
        "Bob": "auburn",
        "Arnold": "black",
    }
    name_fixed_occ = {
        "Bob": "artist",
    }

    # Backtracking state
    house_name = [None] * 6
    house_hair = [None] * 6
    house_occ  = [None] * 6

    remaining_names = set(names)
    remaining_hairs = set(hairs)
    remaining_occs  = set(occs)

    def backtrack(pos):
        if pos == 6:                     # all houses assigned
            return check_full_solution()
        # iterate over possible name choices
        for name in list(remaining_names):
            # early house‑specific constraints
            if name == "Alice" and pos == 3:   # Alice not in house 4 (index 3)
                continue
            if name == "Arnold" and pos == 1:  # Arnold not in house 2 (index 1)
                continue

            # hair options respecting name‑fixed hair
            possible_hairs = remaining_hairs
            if name in name_fixed_hair:
                fixed = name_fixed_hair[name]
                if fixed not in remaining_hairs:
                    continue
                possible_hairs = {fixed}

            for hair in list(possible_hairs):
                # clue 1: brown hair not in house 2 (index 1)
                if hair == "brown" and pos == 1:
                    continue
                # clue 12 already satisfied by name_fixed_hair for Arnold

                # occupation options respecting name‑fixed occ and hair‑doctor link
                possible_occs = remaining_occs
                if name in name_fixed_occ:
                    fixed_occ = name_fixed_occ[name]
                    if fixed_occ not in remaining_occs:
                        continue
                    possible_occs = {fixed_occ}
                # gray hair ↔ doctor
                if hair == "gray":
                    if "doctor" not in remaining_occs:
                        continue
                    possible_occs = {"doctor"}
                if "doctor" in possible_occs and hair != "gray":
                    # doctor must have gray hair, so if we pick doctor here hair must be gray
                    continue

                for occ in list(possible_occs):
                    # enforce gray‑doctor equivalence both ways
                    if occ == "doctor" and hair != "gray":
                        continue
                    if hair == "gray" and occ != "doctor":
                        continue

                    # assign temporarily
                    house_name[pos] = name
                    house_hair[pos] = hair
                    house_occ[pos]  = occ
                    remaining_names.remove(name)
                    remaining_hairs.remove(hair)
                    remaining_occs.remove(occ)

                    # partial checks that involve already placed houses
                    if not partial_ok(pos):
                        # undo and continue
                        remaining_names.add(name)
                        remaining_hairs.add(hair)
                        remaining_occs.add(occ)
                        house_name[pos] = house_hair[pos] = house_occ[pos] = None
                        continue

                    if backtrack(pos + 1):
                        return True

                    # undo
                    remaining_names.add(name)
                    remaining_hairs.add(hair)
                    remaining_occs.add(occ)
                    house_name[pos] = house_hair[pos] = house_occ[pos] = None
        return False

    def partial_ok(current_pos):
        """Check constraints that can be evaluated with the houses filled up to current_pos."""
        # Helper to find index of a given attribute if already assigned
        def idx_of(attr_list, value):
            try:
                return attr_list.index(value)
            except ValueError:
                return None

        # 6. doctor and Bob are next to each other
        bob_idx = idx_of(house_name[:current_pos+1], "Bob")
        doctor_idx = idx_of(house_occ[:current_pos+1], "doctor")
        if bob_idx is not None and doctor_idx is not None:
            if not adjacent(bob_idx, doctor_idx):
                return False

        # 7. engineer directly left of Alice
        alice_idx = idx_of(house_name[:current_pos+1], "Alice")
        eng_idx = idx_of(house_occ[:current_pos+1], "engineer")
        if alice_idx is not None and eng_idx is not None:
            if eng_idx != alice_idx - 1:
                return False

        # 8. Arnold directly left of lawyer
        arnold_idx = idx_of(house_name[:current_pos+1], "Arnold")
        lawyer_idx = idx_of(house_occ[:current_pos+1], "lawyer")
        if arnold_idx is not None and lawyer_idx is not None:
            if arnold_idx != lawyer_idx - 1:
                return False

        # 9. Bob directly left of teacher
        teacher_idx = idx_of(house_occ[:current_pos+1], "teacher")
        if bob_idx is not None and teacher_idx is not None:
            if bob_idx != teacher_idx - 1:
                return False

        # 14. brown hair and Carol are next to each other
        carol_idx = idx_of(house_name[:current_pos+1], "Carol")
        brown_idx = idx_of(house_hair[:current_pos+1], "brown")
        if carol_idx is not None and brown_idx is not None:
            if not adjacent(carol_idx, brown_idx):
                return False

        return True

    def check_full_solution():
        """Validate all clues on a complete assignment."""
        # Build quick lookup dictionaries
        name_at = {house_name[i]: i for i in range(6)}
        hair_at = {house_hair[i]: i for i in range(6)}
        occ_at  = {house_occ[i]: i for i in range(6)}

        # 1. brown hair not in house 2
        if hair_at["brown"] == 1:
            return False
        # 2. Alice not in house 4
        if name_at["Alice"] == 3:
            return False
        # 3. artist is Bob (already enforced)
        # 4. gray hair is the doctor (already enforced)
        # 5. Bob has auburn hair (enforced)
        # 6. doctor and Bob are next to each other
        if not adjacent(name_at["Bob"], occ_at["doctor"]):
            return False
        # 7. engineer directly left of Alice
        if occ_at["engineer"] != name_at["Alice"] - 1:
            return False
        # 8. Arnold directly left of lawyer
        if name_at["Arnold"] != occ_at["lawyer"] - 1:
            return False
        # 9. Bob directly left of teacher
        if name_at["Bob"] != occ_at["teacher"] - 1:
            return False
        # 10. Peter right of brown hair
        if name_at["Peter"] <= hair_at["brown"]:
            return False
        # 11. Arnold not in house 2 (already checked)
        # 12. black hair is Arnold (enforced)
        # 13. doctor right of red hair
        if occ_at["doctor"] <= hair_at["red"]:
            return False
        # 14. brown hair and Carol adjacent (checked in partial, re‑check)
        if not adjacent(hair_at["brown"], name_at["Carol"]):
            return False
        # 15. Arnold left of doctor
        if name_at["Arnold"] >= occ_at["doctor"]:
            return False

        # All constraints satisfied – print result
        for i in range(6):
            print(f"House {i+1}: {house_name[i]}, {house_hair[i]}, {house_occ[i]}")
        return True

    if not backtrack(0):
        print("No solution found", file=sys.stderr)

if __name__ == "__main__":
    solve()

