# Attribute domains
names = ["Peter", "Eric", "Arnold"]
mothers = ["Janelle", "Aniya", "Holly"]
genres = ["romance", "science fiction", "mystery"]
pets = ["cat", "dog", "fish"]

houses = [1, 2, 3]

def satisfies(constraint):
    """Utility to evaluate a boolean expression."""
    return constraint

def solve():
    # Iterate over all permutations for each attribute category
    for name_perm in itertools.permutations(names):
        # map house -> name
        name_of = dict(zip(houses, name_perm))

        # Constraint 5 needs Peter's house, so we can skip early if impossible
        peter_house = next(h for h, n in name_of.items() if n == "Peter")
        # romance must be left of Peter, so Peter cannot be house 1
        if peter_house == 1:
            continue

        for mother_perm in itertools.permutations(mothers):
            mother_of = dict(zip(houses, mother_perm))

            # Constraint 3: distance between Eric and mother Holly is 2
            eric_house = next(h for h, n in name_of.items() if n == "Eric")
            holly_house = next(h for h, m in mother_of.items() if m == "Holly")
            if abs(eric_house - holly_house) != 2:
                continue

            for genre_perm in itertools.permutations(genres):
                genre_of = dict(zip(houses, genre_perm))

                # Constraint 1 & 4 apply to house 1
                if genre_of[1] != "mystery":
                    continue

                # Constraint 5: romance house is directly left of Peter's house
                romance_house = next(h for h, g in genre_of.items() if g == "romance")
                if romance_house != peter_house - 1:
                    continue

                for pet_perm in itertools.permutations(pets):
                    pet_of = dict(zip(houses, pet_perm))

                    # Constraint 1: house 1 pet is dog
                    if pet_of[1] != "dog":
                        continue

                    # Constraint 2: mother Janelle's house has pet fish
                    janelle_house = next(h for h, m in mother_of.items() if m == "Janelle")
                    if pet_of[janelle_house] != "fish":
                        continue

                    # All constraints satisfied – build solution
                    solution = []
                    for h in houses:
                        solution.append(
                            f"House {h}: {name_of[h]}, {mother_of[h]}, {genre_of[h]}, {pet_of[h]}"
                        )
                    return solution
    return None

def main():
    sol = solve()
    if sol:
        for line in sol:
            print(line)

if __name__ == "__main__":
    main()

