heights = ["short", "very short"]
pets = ["cat", "dog"]
nationalities = ["brit", "dane"]
colors = ["yellow", "red"]
mothers = ["Aniya", "Holly"]

houses = [1, 2]

def satisfies(constraints):
    # constraints is a dict mapping (house, attribute) -> value
    # Check clue 1: short is in house 2
    if constraints[(2, "height")] != "short":
        return False
    # Clue 2: Eric is the Dane
    for h in houses:
        if constraints[(h, "name")] == "Eric":
            if constraints[(h, "nationality")] != "dane":
                return False
    # Clue 3: red color is Arnold
    for h in houses:
        if constraints[(h, "color")] == "red":
            if constraints[(h, "name")] != "Arnold":
                return False
    # Clue 4: Holly is directly left of the British person
    # Find house with mother Holly and house with nationality brit
    holly_house = next(h for h in houses if constraints[(h, "mother")] == "Holly")
    brit_house = next(h for h in houses if constraints[(h, "nationality")] == "brit")
    if holly_house + 1 != brit_house:
        return False
    # Clue 5: Holly's person has a cat
    if constraints[(holly_house, "pet")] != "cat":
        return False
    return True

solution = None

# Iterate over all permutations for each attribute category
for name_perm in itertools.permutations(names):
    for height_perm in itertools.permutations(heights):
        for pet_perm in itertools.permutations(pets):
            for nat_perm in itertools.permutations(nationalities):
                for color_perm in itertools.permutations(colors):
                    for mother_perm in itertools.permutations(mothers):
                        # Build constraint dict
                        cons = {}
                        for h, name, height, pet, nat, color, mother in zip(
                            houses, name_perm, height_perm, pet_perm, nat_perm, color_perm, mother_perm
                        ):
                            cons[(h, "name")] = name
                            cons[(h, "height")] = height
                            cons[(h, "pet")] = pet
                            cons[(h, "nationality")] = nat
                            cons[(h, "color")] = color
                            cons[(h, "mother")] = mother
                        if satisfies(cons):
                            solution = cons
                            break
                    if solution:
                        break
                if solution:
                    break
            if solution:
                break
        if solution:
            break
    if solution:
        break

# Output in required format
for h in houses:
    attrs = [
        solution[(h, "name")],
        solution[(h, "height")],
        solution[(h, "pet")],
        solution[(h, "nationality")],
        solution[(h, "color")],
        solution[(h, "mother")]
    ]
    print(f"House {h}: {', '.join(attrs)}")

import itertools

houses = [1, 2, 3]

names = ["Peter", "Arnold", "Eric"]
lunches = ["grilled cheese", "spaghetti", "pizza"]
birthdays = ["april", "jan", "sept"]

def satisfies(constraint):
    return constraint

def solve():
    for name_perm in itertools.permutations(names):
        # mapping house -> name
        house_name = dict(zip(houses, name_perm))
        # reverse lookup
        name_house = {v: k for k, v in house_name.items()}

        # clue 5: Peter directly left of Arnold
        if name_house["Peter"] + 1 != name_house["Arnold"]:
            continue

        for lunch_perm in itertools.permutations(lunches):
            house_lunch = dict(zip(houses, lunch_perm))
            lunch_house = {v: k for k, v in house_lunch.items()}

            # clue 3: Peter loves grilled cheese
            if house_lunch[name_house["Peter"]] != "grilled cheese":
                continue

            # clue 4: Arnold loves spaghetti
            if house_lunch[name_house["Arnold"]] != "spaghetti":
                continue

            for bday_perm in itertools.permutations(birthdays):
                house_bday = dict(zip(houses, bday_perm))
                bday_house = {v: k for k, v in house_bday.items()}

                # clue 1: Arnold's birthday is April
                if house_bday[name_house["Arnold"]] != "april":
                    continue

                # clue 2: Jan birthday left of pizza lover
                jan_house = bday_house["jan"]
                pizza_house = lunch_house["pizza"]
                if not (jan_house < pizza_house):
                    continue

                # all constraints satisfied – output solution
                for h in houses:
                    print(f"House {h}: {house_name[h]}, {house_lunch[h]}, {house_bday[h]}")
                return

