import itertools

# Attribute domains
names = ["Arnold", "Peter", "Bob", "Eric", "Alice"]
hair_colors = ["gray", "brown", "black", "red", "blonde"]
vacations = ["city", "mountain", "camping", "cruise", "beach"]
flowers = ["roses", "tulips", "carnations", "lilies", "daffodils"]
lunches = ["stew", "stir fry", "spaghetti", "pizza", "grilled cheese"]
hobbies = ["painting", "photography", "gardening", "knitting", "cooking"]

# Fixed positions (0‑based indexing)
fixed = {
    "name": {4: "Bob"},
    "flower": {2: "lilies"},
    "hobby": {3: "knitting"},
}

def generate_assignments(values, fixed_positions):
    """Yield all length‑5 lists respecting fixed positions."""
    positions = list(range(5))
    fixed_vals = set(fixed_positions.values())
    free_vals = [v for v in values if v not in fixed_vals]
    free_positions = [p for p in positions if p not in fixed_positions]
    for perm in itertools.permutations(free_vals):
        assign = [None] * 5
        for p, v in fixed_positions.items():
            assign[p] = v
        for p, v in zip(free_positions, perm):
            assign[p] = v
        yield assign

def pos_of(assign, value):
    """Return house index of value in assignment list, or None."""
    try:
        return assign.index(value)
    except ValueError:
        return None

def check(partial):
    """Return True if all applicable constraints are satisfied."""
    # Helper shortcuts
    name = partial.get("name")
    hair = partial.get("hair")
    vac = partial.get("vacation")
    flower = partial.get("flower")
    lunch = partial.get("lunch")
    hobby = partial.get("hobby")

    # 9. Bob is in the fifth house.
    if name and pos_of(name, "Bob") is not None and pos_of(name, "Bob") != 4:
        return False

    # 10. Lilies in third house.
    if flower and pos_of(flower, "lilies") is not None and pos_of(flower, "lilies") != 2:
        return False

    # 11. Knitting in fourth house.
    if hobby and pos_of(hobby, "knitting") is not None and pos_of(hobby, "knitting") != 3:
        return False

    # 15. Carnations not in second house.
    if flower and pos_of(flower, "carnations") == 1:
        return False

    # 1. Stew directly left of Tulips.
    if lunch and flower:
        stew = pos_of(lunch, "stew")
        tulips = pos_of(flower, "tulips")
        if stew is not None and tulips is not None and stew + 1 != tulips:
            return False

    # 2. Camping == Grilled cheese.
    if vac and lunch:
        if pos_of(vac, "camping") is not None and pos_of(lunch, "grilled cheese") is not None:
            if pos_of(vac, "camping") != pos_of(lunch, "grilled cheese"):
                return False

    # 3. Black hair left of Bob.
    if hair and name:
        black = pos_of(hair, "black")
        bob = pos_of(name, "Bob")
        if black is not None and bob is not None and not (black < bob):
            return False

    # 4. Photography == Gray hair.
    if hobby and hair:
        photo = pos_of(hobby, "photography")
        gray = pos_of(hair, "gray")
        if photo is not None and gray is not None and photo != gray:
            return False

    # 5. Pizza == Cruise.
    if lunch and vac:
        pizza = pos_of(lunch, "pizza")
        cruise = pos_of(vac, "cruise")
        if pizza is not None and cruise is not None and pizza != cruise:
            return False

    # 6. Alice prefers city.
    if name and vac:
        alice = pos_of(name, "Alice")
        if alice is not None and vac[alice] != "city":
            return False

    # 7. Beach directly left of Painting.
    if vac and hobby:
        beach = pos_of(vac, "beach")
        painting = pos_of(hobby, "painting")
        if beach is not None and painting is not None and beach + 1 != painting:
            return False

    # 8. Spaghetti == Arnold.
    if lunch and name:
        spaghetti = pos_of(lunch, "spaghetti")
        arnold = pos_of(name, "Arnold")
        if spaghetti is not None and arnold is not None and spaghetti != arnold:
            return False

    # 12. Brown hair directly left of Painting.
    if hair and hobby:
        brown = pos_of(hair, "brown")
        painting = pos_of(hobby, "painting")
        if brown is not None and painting is not None and brown + 1 != painting:
            return False

    # 13. Two houses between Cruise and Knitting.
    if vac and hobby:
        cruise = pos_of(vac, "cruise")
        knitting = pos_of(hobby, "knitting")
        if cruise is not None and knitting is not None and abs(cruise - knitting) != 3:
            return False

    # 14. Red hair == Spaghetti.
    if hair and lunch:
        red = pos_of(hair, "red")
        spaghetti = pos_of(lunch, "spaghetti")
        if red is not None and spaghetti is not None and red != spaghetti:
            return False

    # 16. Eric left of Gardening.
    if name and hobby:
        eric = pos_of(name, "Eric")
        gardening = pos_of(hobby, "gardening")
        if eric is not None and gardening is not None and not (eric < gardening):
            return False

    # 17. Photography == Stew.
    if hobby and lunch:
        photo = pos_of(hobby, "photography")
        stew = pos_of(lunch, "stew")
        if photo is not None and stew is not None and photo != stew:
            return False

    # 18. Eric == Daffodils.
    if name and flower:
        eric = pos_of(name, "Eric")
        daff = pos_of(flower, "daffodils")
        if eric is not None and daff is not None and eric != daff:
            return False

    return True

def solve():
    # Order of categories for backtracking
    categories = ["name", "lunch", "hair", "vacation", "flower", "hobby"]
    # Mapping to domain lists and fixed dicts
    domains = {
        "name": names,
        "hair": hair_colors,
        "vacation": vacations,
        "flower": flowers,
        "lunch": lunches,
        "hobby": hobbies,
    }
    fixed_maps = {
        "name": fixed.get("name", {}),
        "hair": {},
        "vacation": {},
        "flower": fixed.get("flower", {}),
        "lunch": {},
        "hobby": fixed.get("hobby", {}),
    }

    partial = {}

    def backtrack(idx):
        if idx == len(categories):
            # All categories assigned, final check
            if check(partial):
                return True
            return False
        cat = categories[idx]
        for assign in generate_assignments(domains[cat], fixed_maps[cat]):
            partial[cat] = assign
            if check(partial):
                if backtrack(idx + 1):
                    return True
            del partial[cat]
        return False

    if backtrack(0):
        # Build and print solution
        for i in range(5):
            print(f"House {i+1}: {partial['name'][i]}, {partial['hair'][i]}, {partial['vacation'][i]}, {partial['flower'][i]}, {partial['lunch'][i]}, {partial['hobby'][i]}")
    else:
        print("No solution found")

if __name__ == "__main__":
    solve()

