names = ['Arnold', 'Alice', 'Eric', 'Peter']
lunches = ['spaghetti', 'stew', 'pizza', 'grilled cheese']
animals = ['fish', 'horse', 'bird', 'cat']

def satisfies(name_assign, lunch_assign, animal_assign):
    # Eric is in the second house (index 1)
    if name_assign[1] != 'Eric':
        return False

    # The fish enthusiast is Alice
    try:
        fish_idx = animal_assign.index('fish')
    except ValueError:
        return False
    if name_assign[fish_idx] != 'Alice':
        return False

    # The person who is a pizza lover is directly left of the fish enthusiast
    try:
        pizza_idx = lunch_assign.index('pizza')
    except ValueError:
        return False
    if pizza_idx + 1 != fish_idx:
        return False

    # Arnold is the bird keeper
    try:
        arnold_idx = name_assign.index('Arnold')
    except ValueError:
        return False
    if animal_assign[arnold_idx] != 'bird':
        return False

    # The person who loves eating grilled cheese is Peter
    try:
        gc_idx = lunch_assign.index('grilled cheese')
    except ValueError:
        return False
    if name_assign[gc_idx] != 'Peter':
        return False

    # The cat lover and the person who loves the stew are next to each other
    try:
        cat_idx = animal_assign.index('cat')
        stew_idx = lunch_assign.index('stew')
    except ValueError:
        return False
    if abs(cat_idx - stew_idx) != 1:
        return False

    # The person who is a pizza lover is somewhere to the right of Eric
    if pizza_idx <= name_assign.index('Eric'):
        return False

    return True

solution = None
for name_perm in itertools.permutations(names):
    for lunch_perm in itertools.permutations(lunches):
        for animal_perm in itertools.permutations(animals):
