import itertools
import sys

names = ['Eric', 'Arnold', 'Peter', 'Bob', 'Alice', 'Carol']
musics = ['jazz', 'country', 'pop', 'classical', 'rock', 'hip hop']
styles = ['mediterranean', 'modern', 'colonial', 'ranch', 'victorian', 'craftsman']
sports = ['tennis', 'baseball', 'soccer', 'volleyball', 'swimming', 'basketball']
books = ['science fiction', 'historical fiction', 'mystery', 'biography', 'fantasy', 'romance']

# Helper relations
def directly_left(a, b):
    return a + 1 == b

def left_of(a, b):
    return a < b

def right_of(a, b):
    return a > b

def exactly_one_between(a, b):
    return abs(a - b) == 2

def exactly_two_between(a, b):
    return abs(a - b) == 3

# Constraint checker for partial assignments
def consistent(state):
    npos = state['name_pos']
    mpos = state['music_pos']
    spos = state['style_pos']
    sppos = state['sport_pos']
    bpos = state['book_pos']

    # 1. baseball sport = Arnold
    if 'baseball' in sppos and 'Arnold' in npos:
        if sppos['baseball'] != npos['Arnold']:
            return False

    # 2. Alice left of colonial style
    if 'Alice' in npos and 'colonial' in spos:
        if not left_of(npos['Alice'], spos['colonial']):
            return False

    # 3. country directly left of hip hop
    if 'country' in mpos and 'hip hop' in mpos:
        if not directly_left(mpos['country'], mpos['hip hop']):
            return False

    # 4. Peter in Victorian house
    if 'Peter' in npos and 'victorian' in spos:
        if spos['victorian'] != npos['Peter']:
            return False

    # 5. fantasy books = Peter
    if 'fantasy' in bpos and 'Peter' in npos:
        if bpos['fantasy'] != npos['Peter']:
            return False

    # 6. baseball sport = romance book
    if 'baseball' in sppos and 'romance' in bpos:
        if sppos['baseball'] != bpos['romance']:
            return False

    # 7. hip hop left of biography book
    if 'hip hop' in mpos and 'biography' in bpos:
        if not left_of(mpos['hip hop'], bpos['biography']):
            return False

    # 8. ranch style left of romance book
    if 'ranch' in spos and 'romance' in bpos:
        if not left_of(spos['ranch'], bpos['romance']):
            return False

    # 9. Bob swimming
    if 'Bob' in npos and 'swimming' in sppos:
        if sppos['swimming'] != npos['Bob']:
            return False

    #10. romance left of mystery
    if 'romance' in bpos and 'mystery' in bpos:
        if not left_of(bpos['romance'], bpos['mystery']):
            return False

    #11. basketball in house 4
    if 'basketball' in sppos:
        if sppos['basketball'] != 4:
            return False

    #12. Bob jazz
    if 'Bob' in npos and 'jazz' in mpos:
        if mpos['jazz'] != npos['Bob']:
            return False

    #13. Craftsman style = mystery book
    if 'craftsman' in spos and 'mystery' in bpos:
        if spos['craftsman'] != bpos['mystery']:
            return False

    #14. Peter left of basketball
    if 'Peter' in npos and 'basketball' in sppos:
        if not left_of(npos['Peter'], sppos['basketball']):
            return False

    #15. volleyball right of Mediterranean style
    if 'volleyball' in sppos and 'mediterranean' in spos:
        if not right_of(sppos['volleyball'], spos['mediterranean']):
            return False

    #16. Mediterranean style = Alice
    if 'mediterranean' in spos and 'Alice' in npos:
        if spos['mediterranean'] != npos['Alice']:
            return False

    #17. historical fiction directly left of colonial style
    if 'historical fiction' in bpos and 'colonial' in spos:
        if not directly_left(bpos['historical fiction'], spos['colonial']):
            return False

    #18. Carol directly left of pop music
    if 'Carol' in npos and 'pop' in mpos:
        if not directly_left(npos['Carol'], mpos['pop']):
            return False

    #19. one house between pop and classical music
    if 'pop' in mpos and 'classical' in mpos:
        if not exactly_one_between(mpos['pop'], mpos['classical']):
            return False

    #20. two houses between tennis sport and Alice
    if 'tennis' in sppos and 'Alice' in npos:
        if not exactly_two_between(sppos['tennis'], npos['Alice']):
            return False

    return True

def backtrack(pos, state, remaining):
    if pos > 6:
        # all houses assigned, final consistency check
        if consistent(state):
            return state
        return None

    # Determine which sport must be at this position (basketball at 4)
    possible_sports = remaining['sports']
    if pos == 4:
        if 'basketball' not in possible_sports:
            return None
        sport_choices = ['basketball']
    else:
        sport_choices = [s for s in possible_sports if s != 'basketball']

    for name in list(remaining['names']):
        # enforce Mediterranean style = Alice later via constraints
        for music in list(remaining['musics']):
            for style in list(remaining['styles']):
                for sport in sport_choices:
                    for book in list(remaining['books']):
                        # assign
                        state['name_pos'][name] = pos
                        state['music_pos'][music] = pos
                        state['style_pos'][style] = pos
                        state['sport_pos'][sport] = pos
                        state['book_pos'][book] = pos

                        # remove from remaining
                        remaining['names'].remove(name)
                        remaining['musics'].remove(music)
                        remaining['styles'].remove(style)
                        remaining['sports'].remove(sport)
                        remaining['books'].remove(book)

                        if consistent(state):
                            result = backtrack(pos + 1, state, remaining)
                            if result:
                                return result

                        # backtrack restore
                        remaining['names'].append(name)
                        remaining['musics'].append(music)
                        remaining['styles'].append(style)
                        remaining['sports'].append(sport)
                        remaining['books'].append(book)

                        del state['name_pos'][name]
                        del state['music_pos'][music]
                        del state['style_pos'][style]
                        del state['sport_pos'][sport]
                        del state['book_pos'][book]
    return None

def main():
    initial_state = {
        'name_pos': {},
        'music_pos': {},
        'style_pos': {},
        'sport_pos': {},
        'book_pos': {}
    }
    remaining = {
        'names': names[:],
        'musics': musics[:],
        'styles': styles[:],
        'sports': sports[:],
        'books': books[:]
    }

    solution = backtrack(1, initial_state, remaining)
    if not solution:
        print("No solution found", file=sys.stderr)
        return

    # Build reverse lookup for each house
    house_info = {}
    for name, pos in solution['name_pos'].items():
        house_info.setdefault(pos, {})['name'] = name
    for music, pos in solution['music_pos'].items():
        house_info.setdefault(pos, {})['music'] = music
    for style, pos in solution['style_pos'].items():
        house_info.setdefault(pos, {})['style'] = style
    for sport, pos in solution['sport_pos'].items():
        house_info.setdefault(pos, {})['sport'] = sport
    for book, pos in solution['book_pos'].items():
        house_info.setdefault(pos, {})['book'] = book

    for i in range(1, 7):
        h = house_info[i]
        print(f"House {i}: {h['name']}, {h['music']}, {h['style']}, {h['sport']}, {h['book']}")

if __name__ == "__main__":
    main()

