names = ['Arnold', 'Peter', 'Eric']
animals = ['bird', 'horse', 'cat']
months = ['jan', 'sept', 'april']
hobbies = ['photography', 'cooking', 'gardening']
drinks = ['milk', 'water', 'tea']
hairs = ['black', 'brown', 'blonde']

for perm_names in itertools.permutations(names):
    # 3. Eric is not in the first house.
    if perm_names[0] == 'Eric':
        continue
    for perm_animals in itertools.permutations(animals):
        # 4. The cat lover is in the second house.
        if perm_animals[1] != 'cat':
            continue
        # 8. Arnold is the bird keeper.
        idx_arnold = perm_names.index('Arnold')
        if perm_animals[idx_arnold] != 'bird':
            continue
        for perm_months in itertools.permutations(months):
            # 2. The person whose birthday is in April is in the third house.
            if perm_months[2] != 'april':
                continue
            # 10. The person whose birthday is in September is directly left of Arnold.
            idx_sept = perm_months.index('sept')
            if idx_sept != idx_arnold - 1:
                continue
            for perm_hobbies in itertools.permutations(hobbies):
                for perm_drinks in itertools.permutations(drinks):
