                            "name": name_perm[i],
                            "car": car_perm[i],
                            "genre": genre_perm[i],
                            "occ": occ_perm[i],
                        }
                        for i, h in enumerate(houses)
                    }

                    # Clue 7: The person who loves science fiction books is Eric.
                    eric_house = next(h for h in houses if data[h]["name"] == "Eric")
                    if data[eric_house]["genre"] != "science fiction":
                        continue

                    # Clue 1: Science fiction left of teacher
                    sf_house = next(h for h in houses if data[h]["genre"] == "science fiction")
                    teacher_house = next(h for h in houses if data[h]["occ"] == "teacher")
                    if sf_house != teacher_house - 1:
